366	int cublas_activate_device_handles() {
367	  int device = 0;
368	  cudaError_t cuda_status = cudaGetDevice(&device);
369	  if (cuda_status != cudaSuccess) {
370	    return static_cast<int>(cuda_status);
371	  }
372	
373	  auto handle_it = g_cublas_handles_by_device.find(device);
374	  auto prefill_it = g_cublas_prefill_handles_by_device.find(device);
375	  if (handle_it == g_cublas_handles_by_device.end() ||
376	      prefill_it == g_cublas_prefill_handles_by_device.end()) {
377	    return static_cast<int>(cudaErrorInvalidResourceHandle);
378	  }
379	
380	  g_cublas_handle = handle_it->second;
381	  g_cublas_prefill_handle = prefill_it->second;
382	  return static_cast<int>(cudaSuccess);
383	}
